<?php
require __DIR__.'/includes/bootstrap.php';require_user();$user=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=filter_var($_POST['group_id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT booking_group_id,journey_date,status FROM booking_groups WHERE booking_group_id=? AND host_user_id=? FOR UPDATE');$q->execute([$id,$user['user_id']]);$group=$q->fetch();if(!$group||$group['status']!=='Confirmed'||$group['journey_date']<date('Y-m-d'))throw new RuntimeException('This booking is not eligible for cancellation.');$q=$pdo->prepare('UPDATE bookings SET status="Cancelled",seat_id=NULL,cancelled_at=NOW() WHERE booking_group_id=? AND status="Confirmed"');$q->execute([$id]);$q=$pdo->prepare('UPDATE booking_groups SET status="Cancelled",active_host_user_id=NULL,cancelled_at=NOW() WHERE booking_group_id=?');$q->execute([$id]);$pdo->commit();flash('Booking cancelled. Its seats are available again.');}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();flash($exception instanceof RuntimeException?$exception->getMessage():'The booking could not be cancelled.');}go('my-bookings.php');}
$q=$pdo->prepare('SELECT g.*,sc.departure_time,sc.arrival_time,t.train_name,t.train_code,r.route_name,o.station_name AS origin_name,d.station_name AS destination_name FROM booking_groups g JOIN schedules sc ON sc.schedule_id=g.schedule_id JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id JOIN stations o ON o.station_id=r.origin_station_id JOIN stations d ON d.station_id=r.destination_station_id WHERE g.host_user_id=? ORDER BY g.journey_date DESC,g.booking_time DESC');$q->execute([$user['user_id']]);$groups=$q->fetchAll();$passStmt=$pdo->prepare('SELECT * FROM bookings WHERE booking_group_id=? ORDER BY is_guest,booking_id');$pageTitle='My bookings';require __DIR__.'/includes/header.php';?>
<section class="content"><span class="eyebrow">YOUR JOURNEYS</span><h1>My bookings</h1><div class="list"><?php foreach($groups as $g):$passStmt->execute([$g['booking_group_id']]);$passengers=$passStmt->fetchAll();?><article><div><span class="tag"><?=e($g['status'])?> · <?=e($g['booking_ref'])?></span><h3><?=e($g['train_name'])?></h3><p><?=e($g['origin_name'])?> → <?=e($g['destination_name'])?> · <?=e($g['journey_date'])?> · <?=e(substr($g['departure_time'],0,5))?>–<?=e(substr($g['arrival_time'],0,5))?></p><?php foreach($passengers as $p):?><p><?=e($p['is_guest']?'Guest: ':'Passenger: ')?><?=e($p['passenger_name'])?> · <?=e($p['category'])?> / <?=e($p['gender'])?> · <?=e($p['bogie_label'])?> / <?=e($p['seat_label'])?> · <?=e($p['status'])?></p><?php endforeach?><p><a href="<?=e(app_url('ticket.php',['ref'=>$g['booking_ref']]))?>">View e-ticket →</a></p></div><?php if($g['status']==='Confirmed'&&$g['journey_date']>=date('Y-m-d')):?><form method="post"><?php csrf_input();?><input type="hidden" name="group_id" value="<?=e($g['booking_group_id'])?>"><button class="button pale">Cancel booking</button></form><?php endif?></article><?php endforeach?><?php if(!$groups):?><article>No bookings yet. <a href="<?=e(app_url('train-information.php'))?>">Search train schedules</a>.</article><?php endif?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
